-- Grade inicial de 7 dias da Antena Rock, montada com as pastas do acervo atual.
-- Só roda se ainda não houver nenhum programa cadastrado (não sobrescreve o que foi feito no painel).
-- Uso no servidor: cd /opt/radio-online && sudo docker compose -f docker-compose.prod.yml exec -T postgres sh -c 'psql -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB"' < infra/server/grade-inicial.sql
DO $$
DECLARE ids jsonb := '{}';
  pid int;
BEGIN
  IF EXISTS (SELECT 1 FROM "Program") THEN
    RAISE NOTICE 'Já existem programas cadastrados. Nada foi alterado.';
    RETURN;
  END IF;
  ids := ids || jsonb_build_object('madrugada', pid);
  ids := ids || jsonb_build_object('mix', pid);
  ids := ids || jsonb_build_object('ci', pid);
  ids := ids || jsonb_build_object('r70', pid);
  ids := ids || jsonb_build_object('nac', pid);
  ids := ids || jsonb_build_object('coldplay', pid);
  ids := ids || jsonb_build_object('elvis', pid);
  ids := ids || jsonb_build_object('smiths', pid);
  RAISE NOTICE 'Grade criada: % programas.', (SELECT count(*) FROM "Program");
END $$;
